#include "World/AnimalPoseTables.h"

namespace
{
	// The tables themselves, generated by Tools/animal_poses.py (don't edit them by hand).
#include "World/HenPoseData.inl"
#include "World/RoosterPoseData.inl"
#include "World/CatPoseData.inl"

	static_assert(HenPoseCount == static_cast<int32>(EChickenPose::Count), "The hens' table has a row per EChickenPose");
	static_assert(RoosterPoseCount == static_cast<int32>(EChickenPose::Count), "The rooster's table has a row per EChickenPose");
	static_assert(CatPoseCount == static_cast<int32>(ECatPose::Count), "The cat's table has a row per ECatPose");

	FAnimalPoseTable MakeTable(const FAnimalPoseBoneInfo* Bones, int32 NumBones, const FAnimalPoseBone* Rows,
		const TCHAR* const* Names, int32 NumPoses)
	{
		FAnimalPoseTable Table;
		Table.Bones = Bones;
		Table.NumBones = NumBones;
		Table.Rows = Rows;
		Table.PoseNames = Names;
		Table.NumPoses = NumPoses;
		return Table;
	}

	/** A table's rows made into poses, and each one's mirror. */
	struct FAnimalPoseLibrary
	{
		TArray<FAnimalPose> Rows;
		TArray<FAnimalPose> Mirrors;

		explicit FAnimalPoseLibrary(const FAnimalPoseTable& Table)
		{
			for (int32 Pose = 0; Pose < Table.NumPoses; ++Pose)
			{
				Rows.Add(AnimalPose::FromTable(Table, Pose));
				Mirrors.Add(AnimalPose::Mirrored(Table, Rows.Last()));
			}
		}

		const FAnimalPose& Get(int32 Pose, bool bMirrored) const
		{
			const int32 Index = FMath::Clamp(Pose, 0, Rows.Num() - 1);
			return bMirrored ? Mirrors[Index] : Rows[Index];
		}
	};

	const FAnimalPoseLibrary& HenLibrary()
	{
		static const FAnimalPoseLibrary Library(AnimalPoseTables::Hen());
		return Library;
	}

	const FAnimalPoseLibrary& RoosterLibrary()
	{
		static const FAnimalPoseLibrary Library(AnimalPoseTables::Rooster());
		return Library;
	}

	const FAnimalPoseLibrary& CatLibrary()
	{
		static const FAnimalPoseLibrary Library(AnimalPoseTables::Cat());
		return Library;
	}
}

namespace AnimalPoseTables
{
	const FAnimalPoseTable& Hen()
	{
		static const FAnimalPoseTable Table = MakeTable(HenPoseBones, HenBoneCount, &HenPoseRows[0][0], HenPoseNames, HenPoseCount);
		return Table;
	}

	const FAnimalPoseTable& Rooster()
	{
		static const FAnimalPoseTable Table = MakeTable(RoosterPoseBones, RoosterBoneCount, &RoosterPoseRows[0][0], RoosterPoseNames,
			RoosterPoseCount);
		return Table;
	}

	const FAnimalPoseTable& Cat()
	{
		static const FAnimalPoseTable Table = MakeTable(CatPoseBones, CatBoneCount, &CatPoseRows[0][0], CatPoseNames, CatPoseCount);
		return Table;
	}

	const FAnimalPose& Chicken(bool bRooster, EChickenPose Pose, bool bMirrored)
	{
		return (bRooster ? RoosterLibrary() : HenLibrary()).Get(static_cast<int32>(Pose), bMirrored);
	}

	const FAnimalPose& CatPose(ECatPose Pose, bool bMirrored)
	{
		return CatLibrary().Get(static_cast<int32>(Pose), bMirrored);
	}

	const FChickenBones& ChickenBones()
	{
		static const FChickenBones Bones = []()
		{
			const FAnimalPoseTable& Table = Hen();
			FChickenBones Made;
			Made.Body = Table.FindBone(TEXT("body"));
			Made.Neck2 = Table.FindBone(TEXT("neck_2"));
			Made.Head = Table.FindBone(TEXT("head"));
			Made.Jaw = Table.FindBone(TEXT("jaw"));
			Made.Wattles = Table.FindBone(TEXT("wattles"));
			Made.Tail = Table.FindBone(TEXT("tail"));
			Made.TailTip = Table.FindBone(TEXT("tail_tip"));
			for (const TCHAR* Side : { TEXT("_l"), TEXT("_r") })
			{
				for (const TCHAR* Part : { TEXT("thigh"), TEXT("shin"), TEXT("shank"), TEXT("toes"), TEXT("hallux") })
				{
					const int32 Bone = Table.FindBone(FName(FString(Part) + Side));
					if (Bone != INDEX_NONE)
					{
						Made.Legs.Add(Bone);
					}
				}
			}
			for (int32 Bone = 0; Bone < Table.NumBones; ++Bone)
			{
				if (!Made.Legs.Contains(Bone))
				{
					Made.Upper.Add(Bone);
				}
			}
			return Made;
		}();
		return Bones;
	}

	const FCatBones& CatBones()
	{
		static const FCatBones Bones = []()
		{
			const FAnimalPoseTable& Table = Cat();
			FCatBones Made;
			Made.Pelvis = Table.FindBone(TEXT("pelvis"));
			Made.Spine1 = Table.FindBone(TEXT("spine_1"));
			Made.Spine2 = Table.FindBone(TEXT("spine_2"));
			Made.Neck = Table.FindBone(TEXT("neck"));
			Made.Head = Table.FindBone(TEXT("head"));
			Made.EarL = Table.FindBone(TEXT("ear_l"));
			Made.EarR = Table.FindBone(TEXT("ear_r"));
			for (int32 Link = 1; Link <= 6; ++Link)
			{
				const int32 Bone = Table.FindBone(FName(*FString::Printf(TEXT("tail_%d"), Link)));
				if (Bone != INDEX_NONE)
				{
					Made.Tail.Add(Bone);
				}
			}
			return Made;
		}();
		return Bones;
	}
}
